// One-line preview of an exam for the category page.
export function preview(item) {
    if (item.sub) {
        return item.sub;
    }
    const flat = String(item.pages[0].text).split('\n').join(' ');
    return flat.length > 40 ? flat.substring(0, 40) : flat;
}
